'use strict';
const $=(id)=>document.getElementById(id);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=(v,n=27)=>{v=String(v??'');return v.length>n?v.slice(0,n-1)+'…':v};
const fmt=(v)=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(Number(v||0));
const state={view:'dashboard',asof:'2026-11-18',period:'2026-10',peoplePage:0,peopleQuery:'',peopleUnit:'',skill:'',program:'',workflowStatus:'',selectedPosition:null,orgMode:'occupied',zoom:1,orgCache:null,units:[],apiKey:'demo-local-key',busy:false};
const pageTitles={dashboard:'Tổng quan',organization:'Cơ cấu tổ chức',people:'Nhân sự',skills:'Năng lực & kỹ năng',training:'Đào tạo & chứng chỉ',performance:'KPI & hiệu suất',absences:'Nghỉ phép & vắng mặt',workflow:'Phê duyệt & workflow',recognition:'Khen thưởng',discipline:'Hồ sơ kỷ luật',occupational:'Nghề & điều kiện lao động',payroll:'Lương · BHXH · Thuế',immigration:'Chuyên gia nước ngoài'};
async function api(path,options={}){const res=await fetch(path,{...options,headers:{'X-API-Key':state.apiKey,'Content-Type':'application/json',...(options.headers||{})}});let json;try{json=await res.json()}catch{throw Error(`HTTP ${res.status}`)}if(!res.ok)throw Error(json.detail||`HTTP ${res.status}`);return json}
function toast(message,fail=false){const t=$('toast');t.textContent=message;t.style.background=fail?'#9c393d':'#172d4a';t.hidden=false;clearTimeout(toast._timer);toast._timer=setTimeout(()=>t.hidden=true,4200)}
function headline(title,desc,actions=''){return `<section class="page-head"><div><div class="eyebrow">ORGAXIS / ${esc(state.view.toUpperCase())}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></section>`}
function metric(label,value,icon,foot=''){return `<div class="metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-number">${esc(fmt(value))}</div><div class="metric-foot">${foot}</div></div>`}
function panel(title,desc,content,right=''){return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">${title}</h2>${desc?`<p class="panel-hint">${desc}</p>`:''}</div>${right}</div>${content}</section>`}
function tbl(cols,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${cols.length}" class="empty">Không có bản ghi phù hợp</td></tr>`}</tbody></table></div>`}
function badge(value){const s=String(value??'unknown').toLowerCase();const cls=/approved|passed|resolved|valid/.test(s)?'good':/pending|proposed|attended|under_review|unknown|unresolved/.test(s)?'warn':/rejected|failed|expired|suspended/.test(s)?'bad':'neutral';return `<span class="tag ${cls}">${esc(value)}</span>`}
function personLink(p,name){return `<button class="link-btn" data-person="${esc(p)}">${esc(name??p)}</button>`}
function bar(v,max=100,color=''){const p=Math.max(0,Math.min(100,100*Number(v||0)/Math.max(1,max)));return `<div class="bar-track"><div class="bar-fill ${color}" style="width:${p.toFixed(1)}%"></div></div>`}
function errPanel(err){return `<section class="panel"><h2>Không thể tải dữ liệu</h2><p class="muted">${esc(err.message)}</p><button class="btn soft" data-action="retry">Thử lại</button></section>`}
async function navigate(view){if(!pageTitles[view])return;state.view=view;document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.view===view));$('topTitle').textContent=pageTitles[view];$('sidebar').classList.remove('open');location.hash=view;await render()}
async function render(){const content=$('content');content.innerHTML='<div class="loading-shell"><span class="loading-ring"></span><h2>Đang tải dữ liệu...</h2></div>';
try{switch(state.view){
case 'dashboard':content.innerHTML=await dashboard();break;
case 'organization':content.innerHTML=await organization();break;
case 'people':content.innerHTML=await people();break;
case 'skills':content.innerHTML=await skills();break;
case 'training':content.innerHTML=await training();break;
case 'performance':content.innerHTML=await performance();break;
case 'absences':content.innerHTML=await absences();break;
case 'workflow':content.innerHTML=await workflow();break;
case 'recognition':content.innerHTML=await recognition();break;
case 'discipline':content.innerHTML=await discipline();break;
case 'occupational':content.innerHTML=await occupational();break;
case 'payroll':content.innerHTML=await payroll();break;
case 'immigration':content.innerHTML=await immigration();break;
}}
catch(e){content.innerHTML=errPanel(e);toast(e.message,true)}
}
async function dashboard(){const [d,or,people,tr,perf]=await Promise.all([api('/v1/dashboard?as_of='+state.asof),api('/v1/org/blank?as_of='+state.asof),api('/v1/people/search?limit=1000&as_of='+state.asof),api('/v1/training/programs'),api('/v1/performance?period='+state.period)]);
state.units=or.units;const depts={};people.items.forEach(p=>{const k=p.unit_name||'Chưa phân công';depts[k]=(depts[k]||0)+1});const deptRows=Object.entries(depts).sort((a,b)=>b[1]-a[1]).slice(0,7);
const modules=[['organization','◇','Cấu trúc theo thời gian','Xem quan hệ báo cáo và vị trí trống'],['people','♙','Hồ sơ nhân sự','Tra cứu 1.000 hồ sơ và lịch sử phân công'],['skills','◎','Năng lực đa kỹ năng','Ma trận kỹ năng, đánh giá và thời hạn'],['training','▤','Đào tạo & chứng nhận','Lượt đào tạo và tình trạng còn hiệu lực'],['performance','▥','KPI & hiệu suất','Kết quả theo tháng và theo từng người'],['workflow','⇢','Workflow','Tuyến duyệt, hồ sơ và quyết định']];
let changeLines=or.unit_count;
return headline('Trung tâm quản trị nhân lực','Một nguồn dữ liệu về tổ chức, năng lực, hiệu suất và thẩm quyền — truy vấn theo thời điểm.',`<button class="btn soft" data-view="organization">Xem cơ cấu</button><button class="btn" data-view="people">Khám phá nhân sự <span style="margin-left:6px">↗</span></button>`)+
`<section class="cards4">${metric('Nhân sự đang phân công',d.active_people,'♙','Tại ngày '+esc(state.asof))}${metric('Đơn vị tổ chức',or.unit_count,'◇','Sơ đồ theo ngày hiệu lực')}${metric('Hồ sơ năng lực',d.totals.person_skill,'◎','16 nhóm kỹ năng chuẩn hóa')}${metric('Workflow đang chờ',d.workflow_pending,'⇢','Cần xử lý theo thẩm quyền')}</section>`+
`<div class="columns-2">${panel('Phân bổ nhân lực theo đơn vị','Số người đang giữ vị trí tại ngày '+state.asof,`<div>${deptRows.map(([name,n])=>`<div class="axis-row"><span title="${esc(name)}">${esc(short(name,21))}</span>${bar(n,Math.max(...deptRows.map(v=>v[1])))}<b>${fmt(n)}</b></div>`).join('')}</div><div class="footnote">${people.total} người · Phân bổ theo position placement hiện hành</div>`)}${panel('Workforce readiness','Số liệu thực từ database seed, không phải số được vẽ sẵn',`<div class="compact-list">${[
['Tổng lượt đào tạo',d.totals.training_record,'đã ghi nhận'],['Hồ sơ sắp hết hiệu lực',d.training_expiring_45d,'trong 45 ngày sau '+state.asof],['Kết quả KPI',d.totals.kpi_result,'dòng chỉ tiêu'],['Yêu cầu nghỉ/vắng',d.totals.absence_case,'hồ sơ'],['Khen thưởng',d.totals.recognition_case,'hồ sơ']].map(([l,n,h])=>`<div class="compact-item"><div><strong>${l}</strong><span>${h}</span></div><b>${fmt(n)}</b></div>`).join('')}</div>`)} </div>`+
`${panel('Ứng dụng nghiệp vụ','Mở một module để xem dữ liệu, thao tác và lịch sử — không phải các thẻ thông tin giả lập',`<div class="module-grid">${modules.map(([id,ico,title,desc])=>`<button class="module-tile" data-view="${id}"><span class="module-ico">${ico}</span><strong>${title}</strong><p>${desc}</p></button>`).join('')}</div>`)}`+
`<div class="columns-2-even">${panel('Cơ cấu & thay đổi theo ngày','Thử mốc 2026-06-30, 2026-07-01 và 2027-01-01',`<div class="compact-list">${(await api('/v1/org/changes')).map(v=>`<div class="compact-item"><div class="item-main"><span class="initial">${v.effective_date.slice(5,7)}</span><div><strong>${esc(v.title)}</strong><span>Hiệu lực ${esc(v.effective_date)}</span></div></div>${badge(v.status)}</div>`).join('')}</div><div style="margin-top:16px"><button class="btn soft" data-view="organization">Mở Temporal Org Chart →</button></div>`)}${panel('Hiệu suất kỳ '+state.period,'Tổng hợp trung bình các nhóm KPI',`<div class="compact-list">${perf.metrics.slice(0,5).map(m=>`<div class="compact-item"><div style="width:100%;display:grid;grid-template-columns:125px 1fr 50px;align-items:center;gap:12px"><strong>${esc(m.metric_code)}</strong>${bar(m.average_actual,m.average_target)}<b style="text-align:right">${fmt(m.average_actual)}%</b></div></div>`).join('')}</div>`)} </div>`+
`<p class="footnote">ORGAXIS PILOT · Toàn bộ hồ sơ trong môi trường này là dữ liệu giả lập. Phân loại lao động và kết quả KPI không tạo ra kết luận pháp lý hay quyết định nhân sự tự động.</p>`
}
async function organization(){const [b,o,changes]=await Promise.all([api('/v1/org/blank?as_of='+state.asof),api('/v1/org/occupied?as_of='+state.asof+'&limit=1000'),api('/v1/org/changes')]);state.units=b.units;const staff={};for(const a of o.assignments){(staff[a.position_code]??=[]).push(a)}
state.orgCache={b,o,staff};
let display=orgSVG(b,staff);return headline('Cấu trúc tổ chức động','Xem tổ chức theo ngày hiệu lực; chọn vị trí để xem người đảm nhiệm, cấp trên và quan hệ báo cáo.',`<button class="btn soft" data-action="org-fit">Vừa khung</button><button class="btn" data-action="report-change">Đổi tuyến báo cáo</button>`)+
`<section class="cards4">${metric('Đơn vị',b.unit_count,'◇','Blank org theo ngày')}${metric('Nhóm vị trí',b.position_count,'▥','Danh mục position')}${metric('Người được phân công',o.total,'♙','Tại '+state.asof)}${metric('Đợt thay đổi cơ cấu',changes.length,'◷','Tổng lịch sử cấu trúc')}</section>`+
`${panel('Temporal Organization Map','Đây là cây Position Reporting. Blank Org Chart độc lập với người đang giữ vị trí.',`<div class="org-layout"><div class="org-sidebar"><div class="divider-title">Đơn vị tổ chức</div>${b.units.map(u=>`<button class="unit-tree-item" data-unit="${esc(u.code)}"><span class="unit-dot"></span><span><b>${esc(u.name)}</b><br><span class="tiny muted">${esc(u.code)} · ${esc(u.unit_type)}</span></span></button>`).join('')}<div class="line"></div><div class="divider-title">Thay đổi có hiệu lực</div>${changes.map(c=>`<button class="unit-tree-item" data-change-date="${esc(c.effective_date)}"><span class="unit-dot" style="background:#d2a051"></span><span>${esc(short(c.title,28))}<br><span class="tiny muted">${esc(c.effective_date)}</span></span></button>`).join('')}</div><div class="org-area"><div class="org-toolbar"><div class="pill-toggle"><button data-orgmode="occupied" class="${state.orgMode==='occupied'?'selected':''}">Occupied chart</button><button data-orgmode="blank" class="${state.orgMode==='blank'?'selected':''}">Blank structure</button></div><div class="toolbar"><span class="tiny muted">Zoom</span><button class="btn soft small" data-action="org-minus">−</button><button class="btn soft small" data-action="org-plus">+</button></div></div><div class="org-view" id="orgView">${display}</div><div class="org-selection" id="orgSelection"><div><h3>Chọn một vị trí trên sơ đồ</h3><p>Hiển thị người đảm nhiệm, đơn vị trực thuộc và các liên kết báo cáo.</p></div></div><div class="legend" style="margin-top:12px"><span class="tiny"><i style="background:#2b62a8"></i> Vị trí quản lý</span><span class="tiny"><i style="background:#1b9584"></i> Vị trí vận hành</span><span class="tiny"><i style="background:#d8a24f"></i> Chưa có người đảm nhiệm</span></div></div></div>`)}`;
}
function orgSVG(b,staff){const pp=b.positions;const map=Object.fromEntries(pp.map(p=>[p.id,p]));const children={};pp.forEach(p=>{let par=map[p.supervisor_position_id]?p.supervisor_position_id:'root';(children[par]??=[]).push(p)});Object.values(children).forEach(arr=>arr.sort((a,b)=>a.code.localeCompare(b.code)));
let positions={},leaves=0,maxDepth=0;function layout(p,depth){maxDepth=Math.max(depth,maxDepth);const cs=children[p.id]||[];if(cs.length){const xs=cs.map(x=>layout(x,depth+1));positions[p.id]={x:(xs[0]+xs[xs.length-1])/2,y:depth*160+55};}else{positions[p.id]={x:135+(leaves++)*263,y:depth*160+55}}return positions[p.id].x}
(children.root||[]).forEach(p=>layout(p,0));let width=Math.max(850,leaves*263+130),height=(maxDepth+1)*160+105;
let lines='',nodes='';for(const p of pp){const a=positions[p.id];if(!a)continue;const to=p.supervisor_position_id&&positions[p.supervisor_position_id];if(to)lines+=`<path d="M${to.x} ${to.y+55}V${to.y+85} Q${to.x} ${to.y+97} ${a.x} ${a.y-17} V${a.y}" fill="none" stroke="#b4c7dc" stroke-width="1.75" stroke-linecap="round"/>`;}
for(const p of pp){const a=positions[p.id];if(!a)continue;const holders=(staff[p.code]||[]);const isMgr=(p.holder_limit===1);const empty=holders.length===0;const blank=state.orgMode==='blank';const accent=blank?(isMgr?'#315d9c':'#239487'):(empty?'#cc9347':isMgr?'#315d9c':'#239487');const active=(state.selectedPosition===p.id);nodes+=`<g class="svg-node" data-position="${esc(p.id)}" tabindex="0" role="button" aria-label="${esc(p.title)}" transform="translate(${a.x-109},${a.y})"><rect class="card-node" width="218" height="109" rx="10" fill="#ffffff" stroke="${active?'#2f64ad':'#dae4ef'}" stroke-width="${active?'2.5':'1'}"/><rect x="0" y="0" width="4" height="109" rx="2" fill="${accent}"/><text x="16" y="26" fill="#2c4059" font-size="12.5" font-weight="750">${esc(short(p.title,27))}</text><text x="16" y="44" fill="#8493a5" font-size="10">${esc(p.code)} · ${esc(p.org_unit_id?.replace('OU-','')||'')}</text><path d="M15 54 H201" stroke="#edf1f6"/><text x="16" y="76" fill="${empty?'#b77d2d':'#4d6179'}" font-size="11" font-weight="650">${blank?'Vị trí trong cơ cấu':empty?'Vị trí chưa phân công':isMgr?esc(short(holders[0]?.display_name,28)):esc(fmt(holders.length))+' nhân sự'}</text><text x="16" y="95" fill="#94a2b2" font-size="9.5">${state.orgMode==='blank'?'Định biên '+esc(p.holder_limit):esc(fmt(holders.length))+' / '+esc(fmt(p.holder_limit))+' đang đảm nhiệm'}</text></g>`}
return `<svg id="orgSvg" xmlns="http://www.w3.org/2000/svg" width="${width*state.zoom}" height="${height*state.zoom}" viewBox="0 0 ${width} ${height}" aria-label="Temporal reporting org chart"><defs><filter id="cshadow"><feDropShadow dx="0" dy="2" stdDeviation="4" flood-opacity=".06"/></filter></defs>${lines}${nodes}</svg>`
}
async function people(){let url='/v1/people/search?as_of='+state.asof+'&limit=40&offset='+state.peoplePage*40+'&q='+encodeURIComponent(state.peopleQuery)+'&unit='+encodeURIComponent(state.peopleUnit);const res=await api(url);let opts='<option value="">Tất cả đơn vị</option>'+state.units.map(u=>`<option value="${esc(u.code)}" ${state.peopleUnit===u.code?'selected':''}>${esc(u.name)}</option>`).join('');if(!state.units.length){let b=await api('/v1/org/blank?as_of='+state.asof);state.units=b.units;opts='<option value="">Tất cả đơn vị</option>'+b.units.map(u=>`<option value="${esc(u.code)}">${esc(u.name)}</option>`).join('')}
const rows=res.items.map(x=>`<tr><td><div class="item-main"><span class="initial">${esc((x.display_name||'N').split(' ').slice(0,1)[0].slice(0,2))}</span><div><strong>${personLink(x.id,x.display_name)}</strong><div class="tiny muted">${esc(x.id)}</div></div></div></td><td>${esc(x.position_title||'Chưa phân công')}<div class="tiny muted">${esc(x.position_code)}</div></td><td>${esc(x.unit_name||'—')}</td><td>${esc(x.assigned_from||'—')}</td><td>${badge(x.position_code?'Đang phân công':'Unassigned')}</td><td><button class="btn soft tiny" data-person="${esc(x.id)}">Hồ sơ ↗</button></td></tr>`);
return headline('Danh bạ nhân sự','Tìm kiếm nhân viên, theo dõi vị trí, lịch sử chuyển công tác và hồ sơ nghiệp vụ theo thời gian.',`<button class="btn soft" data-action="people-refresh">Tải lại</button><button class="btn" data-action="hire-add">+ Nhân sự mới (demo)</button>`)+
`${panel('Nhân sự trong tổ chức',`${fmt(res.total)} nhân sự phù hợp · Hiển thị tại ${state.asof}`,`<div class="toolbar" style="margin-bottom:16px"><input class="input" id="peopleQ" value="${esc(state.peopleQuery)}" placeholder="Tìm theo tên / mã EMP..."/><select class="select" id="peopleUnit">${opts}</select><button class="btn" data-action="people-filter">Lọc</button><button class="btn soft" data-action="people-clear">Đặt lại</button></div>${tbl(['NHÂN SỰ','CHỨC DANH / VỊ TRÍ','ĐƠN VỊ','TỪ NGÀY','TRẠNG THÁI',''],rows)}<div class="pager"><span>Trang ${state.peoplePage+1} / ${Math.max(1,Math.ceil(res.total/40))}</span><button class="btn soft tiny" data-action="people-prev" ${state.peoplePage===0?'disabled':''}>← Trước</button><button class="btn soft tiny" data-action="people-next" ${(state.peoplePage+1)*40>=res.total?'disabled':''}>Tiếp →</button></div>`)}`
}
async function skills(){const [cat,holders]=await Promise.all([api('/v1/skills/catalog'),api('/v1/skills/holders?limit=80'+(state.skill?'&skill='+encodeURIComponent(state.skill):''))]);let max=Math.max(1,...cat.items.map(x=>+x.holders));let rows=holders.items.map(x=>`<tr><td>${personLink(x.person_id,x.display_name)}<div class="tiny muted">${esc(x.person_id)}</div></td><td>${esc(x.label)}</td><td><span class="tag blue">L${esc(x.level)}</span></td><td>${esc(x.assessed_at)}</td><td>${esc(x.valid_until||'Không ghi hạn')}</td></tr>`);
return headline('Ma trận năng lực','Một người có thể có nhiều kỹ năng. Năng lực được đánh giá độc lập với chức vụ và nhiệm vụ thực tế.',`<button class="btn" data-action="skill-add">+ Đánh giá kỹ năng</button>`)+
`<section class="cards4">${metric('Danh mục kỹ năng',cat.items.length,'◎','Nhóm năng lực')}${metric('Lượt đánh giá',cat.items.reduce((v,x)=>v+ +x.holders,0),'♙','Hồ sơ person_skill')}${metric('Đạt mức L3–L4',cat.items.reduce((v,x)=>v+ +x.proficient,0),'✓','Mức năng lực nội bộ')}${metric('Nhân sự đa kỹ năng',cat.people_multiskill,'◇','Có ít nhất 2 kỹ năng') }</section>`+
`<div class="columns-2">${panel('Mức độ phủ kỹ năng','Chọn kỹ năng để lọc danh sách nhân sự',`<div class="compact-list">${cat.items.map(x=>`<button class="unit-tree-item ${state.skill===x.code?'active':''}" style="display:grid;grid-template-columns:1fr 135px 42px;gap:9px" data-skill="${esc(x.code)}"><span>${esc(x.label)}</span>${bar(x.holders,max)}<b style="text-align:right">${fmt(x.holders)}</b></button>`).join('')}</div>`)}${panel('Danh sách nhân sự có kỹ năng',state.skill?'Đang lọc: '+state.skill:'Hiển thị 80 hồ sơ đầu tiên',`<div class="toolbar" style="margin-bottom:12px"><button class="btn soft small" data-skill="">Tất cả kỹ năng</button></div>${tbl(['NHÂN SỰ','NĂNG LỰC','MỨC','NGÀY ĐÁNH GIÁ','HẾT HẠN'],rows)}`)}</div>`+await eligibilityPanel();
}
async function training(){const [pg,rr]=await Promise.all([api('/v1/training/programs'),api('/v1/training/records?limit=70'+(state.program?'&program='+encodeURIComponent(state.program):''))]);let count=pg.items.reduce((n,x)=>n+(+x.attendees),0);
return headline('Đào tạo & chứng chỉ','Theo dõi lịch sử học tập, kết quả sát hạch và hiệu lực; không tự suy ra tình trạng pháp lý từ việc tham gia khóa học.',`<button class="btn" data-action="training-add">+ Ghi nhận đào tạo</button>`)+
`<section class="cards4">${metric('Chương trình',pg.items.length,'▤','Danh mục versioned')}${metric('Lượt tham dự',count,'♙','Training records')}${metric('Nhà máy',2,'⌂','Mẫu dữ liệu nhiều nhà máy')}${metric('Mức đánh giá','3','✓','Passed / attended / failed')}</section>`+
`<div class="columns-2">${panel('Chương trình đào tạo','Nhấn để lọc danh sách học viên',`<div class="compact-list">${pg.items.map(x=>`<button class="unit-tree-item ${state.program===x.id?'active':''}" data-program="${esc(x.id)}"><span class="initial" style="background:#e8f2f6">${esc(x.name.slice(0,2))}</span><span style="flex:1"><b>${esc(x.name)}</b><br><span class="tiny muted">${esc(short(x.regulatory_basis,50))}</span></span><span class="tag blue">${fmt(x.attendees)}</span></button>`).join('')}</div>`)}${panel('Lịch sử huấn luyện gần đây',`70 bản ghi · ${state.program?'Đang lọc chương trình':'Toàn bộ chương trình'}`,`<button class="btn soft tiny" style="margin-bottom:12px" data-program="">Xóa bộ lọc</button>${tbl(['NHÂN SỰ','CHƯƠNG TRÌNH','KẾT QUẢ','NGÀY','HIỆU LỰC'],rr.items.map(x=>`<tr><td>${personLink(x.person_id,x.display_name)}</td><td>${esc(x.program)}</td><td>${badge(x.result)}</td><td>${esc(x.completed_on)}</td><td>${esc(x.valid_until||'—')}</td></tr>`))}`)}</div>`
}
async function performance(){let result=await api('/v1/performance?period='+state.period);let metrics=result.metrics;const achieved=metrics.reduce((v,m)=>v+ +m.reached,0),total=metrics.reduce((v,m)=>v+ +m.records,0);
return headline('KPI & hiệu suất','Đánh giá theo kỳ, theo chỉ tiêu và cá nhân. Điểm KPI không tự động trở thành quyết định kỷ luật.',`<button class="btn" data-action="kpi-add">+ Ghi nhận KPI</button>`)+
`<section class="cards4">${metric('Dòng chỉ tiêu',total,'▥','Kỳ '+state.period)}${metric('Chỉ tiêu đạt',achieved,'✓','Actual ≥ target')}${metric('Tỷ lệ đạt',Math.round(100*achieved/Math.max(1,total)),'%','Đơn vị phần trăm')}${metric('Loại chỉ tiêu',metrics.length,'◇','Metric codes')}</section>`+
`${panel('Hiệu suất theo nhóm KPI','Chọn kỳ đánh giá để xem kết quả thực tế',`<div class="toolbar" style="margin-bottom:15px"><label class="tiny muted">Kỳ:</label><input type="month" class="input" id="kpiPeriod" value="${esc(state.period)}" style="min-width:160px"><button class="btn soft" data-action="kpi-period">Áp dụng</button></div><div class="cards3">${metrics.map(m=>`<div class="metric-card"><div class="metric-top"><b class="tiny muted">${esc(m.metric_code)}</b>${badge(fmt(100*m.reached/Math.max(1,m.records))+'% đạt')}</div><div class="metric-number" style="font-size:24px">${fmt(m.average_actual)}<span style="font-size:12px;color:#8995a5;font-weight:600"> / ${fmt(m.average_target)}</span></div>${bar(m.average_actual,m.average_target)}<div class="metric-foot">${fmt(m.records)} kết quả · ${fmt(m.reached)} đạt mục tiêu</div></div>`).join('')}</div>`)}`+
`${panel('Kết quả cá nhân','80 kết quả đứng đầu theo tỷ lệ đạt mục tiêu',tbl(['NHÂN SỰ','CHỈ TIÊU','THỰC HIỆN','MỤC TIÊU','TỶ LỆ'],result.results.map(v=>`<tr><td>${personLink(v.person_id,v.display_name)}</td><td>${esc(v.metric_code)}</td><td><b>${fmt(v.actual)}</b></td><td>${fmt(v.target)}</td><td>${badge(fmt(v.actual/v.target*100)+'%')}</td></tr>`)))}`;
}
